account-configurator.scss:
@import "global-objects";

#main-content{
  margin: 0;
  background: #f6f5f2;

  input[type="search"]{
    box-sizing: border-box;
  }
    > .container {
        margin: 0;
        padding: 0 15px;
        max-width: none;
        width: 100%;
    }
}


.account-configurator {
  color: #000;
  font-family: var(--serif, Georgia, serif);
  margin: 0;
  max-width: none;
  min-height: 70vh;
  padding: 48px var(--gutter, 24px) 110px;

  *, *::before, *::after { box-sizing: border-box; }

  &__inner { margin: 0 auto; max-width: 1400px; }

  &__header {
    margin-bottom: 32px;
    max-width: 720px;

    h1 {
      font-family: var(--sans, Arial, sans-serif);
      font-size: clamp(36px, 5vw, 38px);
      font-weight: 300;
      line-height: 1.05;
      margin: 10px 0 14px;
    }

    p { color: #000; font-size: 18px; line-height: 1.5; margin: 0; }
  }

  &__eyebrow,
  &__section-label {
    display: block;
    font-family: var(--sans-ext, Arial, sans-serif);
    font-size: 16px;
    font-weight: 600;
    letter-spacing: .04em;
    text-transform: uppercase;
  }

  &__card {
    --card-padding-x: clamp(24px, 4vw, 42px);
    --card-padding-y: clamp(24px, 4vw, 42px);
    background: var(--white, #fff);
    border: 1px solid var(--hair, #dedbd5);
    box-shadow: 0 10px 30px rgba(0, 0, 0, .07);
    margin-bottom: 24px;
    padding: var(--card-padding-y) var(--card-padding-x);

    h2 { font-family: var(--sans, Arial, sans-serif); font-size: 28px; font-weight: 400; margin: 0 0 22px; }
    h3 { font-family: var(--sans, Arial, sans-serif); font-size: 22px; font-weight: 500; margin: 0 0 6px; }
    p { color: #000; font-size: 16px; line-height: 1.5; margin: 4px 0; }
  }

  &__search {
    display: grid;
    gap: 12px;
    grid-template-columns: minmax(0, 1fr) auto;

    input {
      background: #fff;
      border: 1px solid var(--hair-strong, #aaa);
      border-radius: 0;
      color: inherit;
      font: inherit;
      font-size: 16px;
      min-height: 32px;
      padding: 12px 16px;
      width: 100%;

      &:focus { border-color: var(--royal, #243b80); outline: 2px solid rgba(36, 59, 128, .16); outline-offset: 1px; outline: none !important; }
    }
  }

  &__button,
  &__status {
    align-items: center;
    background: #000;
    border: 1px solid #000;
    border-radius: 0;
    color: var(--white, #fff);
    cursor: pointer;
    display: inline-flex;
    font-family: var(--sans-ext, Arial, sans-serif);
    font-size: 16px;
    font-weight: 600;
    justify-content: center;
    min-height: 52px;
    padding: 12px 24px;

    &:hover { background: #fff; color: #000; }
    &:disabled { cursor: wait; opacity: .55; }
  }

  &__message { color: #000; font-size: 16px; min-height: 24px; padding-top: 12px;  margin-bottom: 20px;}
  &__results { display: grid; gap: 14px; }

  &__company {
    align-items: center;
    border: 1px solid var(--hair, #dedbd5);
    display: grid;
    gap: 24px;
    grid-template-columns: minmax(0, 1fr) auto;
    padding: 20px;
    transition: background-color .2s ease, box-shadow .2s ease;

    &:hover {
      background: #fafafa;
      box-shadow: 0 6px 18px rgba(0, 0, 0, .06);
    }

    h3 { font-family: var(--sans, Arial, sans-serif); font-size: 21px; margin: 0 0 8px; color: #000000; font-weight: 600; }
    p { color: #000; font-size: 16px; line-height: 1.4; margin: 2px 0; }
  }

  &__status {
    background: #fff;
    color: #000;
    min-width: 160px;
    &.is-configured { background: #000; color: #fff; }
  }

  &__selected {
    border-left: 5px solid var(--royal, #243b80);
    margin-top: 32px;
    h2 { margin: 12px 0 8px; }
  }

  &__form { display: grid; gap: 38px 28px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  &__type,
  &__actions { grid-column: 1 / -1; }

  &__field > span,
  &__columns h3,
  &__products h3,
  &__approved h4,
  #company-search-title {
    color: #000;
    font-size: 20px;
    font-weight: 600;
    line-height: 1.3;
  }

  &__field {
    display: grid;
    gap: 8px;
    max-width: 560px;

    > span { font-family: var(--sans, Arial, sans-serif); font-size: 20px; font-weight: 600; }
    small { color: #000; font-size: 16px; }
    select {
      background: #fff;
      border: 1px solid var(--hair-strong, #aaa);
      border-radius: 0;
      color: inherit;
      font: inherit;
      font-size: 16px;
      min-height: 52px;
      padding: 12px;
    }
    select[multiple] { min-height: 190px; }
  }

  &__columns { display: contents; }
  &__columns[hidden] { display: none; }
  &__brand-list,
  &__products { order: 1; }
  &__products { grid-column: 1 / -1; }
  &__prohibited-brands { order: 2; }
  &__category-list { order: 3; }
  &__actions { order: 4; }

  &__brand-list,
  &__category-list,
  &__prohibited-brands {
    > h3,
    > span {
      height: 26px;
      line-height: 26px;
      margin: 0;
    }

    > p,
    > small {
      box-sizing: border-box;
      display: block;
      height: 48px;
      line-height: 1.5;
      margin: 4px 0 0;
    }

    > .account-configurator__check-list {
      height: 320px;
      margin-top: 0;
      max-height: none;
    }
  }

  &__prohibited-brands { gap: 0; }
  &__prohibited-brands[hidden] { display: none; }

  &__selected-count {
    color: #000;
    font-size: 16px;
    line-height: 1.5;
    margin-bottom: 10px;
  }

  &__select-all {
    align-items: center;
    color: #000;
    cursor: pointer;
    display: flex;
    font-size: 16px;
    font-weight: 600;
    gap: 10px;
    margin: 0 0 10px;

    input { flex: 0 0 auto; height: 18px; margin: 0; width: 18px; }
    span { font-size: 16px; line-height: 1.4; margin: 0; }
  }

  &__list-filter {
    background: #fff;
    border: 1px solid var(--hair-strong, #aaa);
    border-radius: 0;
    color: #000;
    font-family: inherit;
    font-size: 16px;
    min-height: 48px;
    padding: 10px 14px;
    width: 100%;

    &:focus { border-color: var(--royal, #243b80); outline: none; }
  }

  &__list-filter + &__check-list { margin-top: 8px; }

  &__check-list {
    border: 1px solid var(--hair, #dedbd5);
    margin-top: 14px;
    max-height: 320px;
    overflow: auto;
    padding: 8px 16px;

    ul { list-style: none; margin: 0; padding: 0; }
    li { border-bottom: 1px solid var(--hair, #dedbd5); font-size: 16px; margin: 0; padding: 0 0 0 calc(var(--tree-depth, 0) * 18px); }
    li.is-shop-category { display: none; }
    li:last-child { border-bottom: 0; }
    label { align-items: flex-start; cursor: pointer; display: flex; gap: 12px; line-height: 1.4; margin: 0 -10px; padding: 12px 10px; transition: background-color .2s ease; }
    label:hover { background: #f3f3f3; }
    label:has(input:checked) { background: #f7f7f7; }
    li.is-parent > label > span { font-weight: 600; }
    input { flex: none; height: 18px; margin: 2px 0 0; width: 18px; }
    strong, small { display: block; font-size: 16px; }
    small { color: #000; margin-top: 3px; }
  }

  &__products { border-top: 1px solid var(--hair, #dedbd5); padding-top: 32px; }
  &__products[hidden] { display: none; }
  &__products &__check-list label { align-items: center; }
  &__products &__check-list input { margin-top: 0; }

  &__bulk-toggle {
    background: transparent;
    border: 0;
    border-bottom: 1px solid currentColor;
    color: #000;
    cursor: pointer;
    font-size: 16px;
    font-weight: 600;
    margin: 14px 0 0;
    padding: 2px 0;
  }

  &__bulk-panel { margin-top: 14px; }
  &__bulk-panel[hidden] { display: none; }
  &__bulk-help { margin-bottom: 12px; }
  &__bulk-import {
    align-items: stretch;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    margin-bottom: 6px;

    textarea {
      border: 1px solid var(--hair, #c9c9c9);
      border-radius: 0;
      color: #000;
      font-size: 16px;
      line-height: 1.5;
      min-height: 112px;
      padding: 14px 16px;
      resize: vertical;
      &:focus{
        outline: none !important;
      }
    }

    .account-configurator__button { align-self: stretch; }
  }

  &__product { align-items: center; display: flex; gap: 14px; min-width: 0; }
  &__product-image { background: #ffffff; flex: 0 0 72px; height: 72px; object-fit: contain; width: 72px; }

  &__approved {
    margin-top: 24px;
    h4 { font-family: var(--sans, Arial, sans-serif); margin: 0 0 10px; }
    article { align-items: center; border-top: 1px solid var(--hair, #dedbd5); display: flex; justify-content: space-between; margin: 0 -10px; padding: 15px 10px; transition: background-color .2s ease; }
    article:hover { background: #ffffff; }
    strong, span { display: block; font-size: 16px; }
    span { color: #000; margin-top: 4px; }
    button { background: transparent; border: 0; border-bottom: 1px solid currentColor; color: var(--crimson, #9e1b32); cursor: pointer; font-size: 16px; padding: 3px 0; }
  }

  &__actions {
    align-items: center;
    background: #fff;
    border-top: 1px solid var(--hair, #dedbd5);
    bottom: 0;
    display: flex;
    gap: 24px;
    justify-content: flex-end;
    margin: 0 calc(-1 * var(--card-padding-x)) calc(-1 * var(--card-padding-y));
    padding: 20px var(--card-padding-x);
    position: sticky;
    z-index: 5;
  }

  &__clear-filters {
    background: #fff;
    border: 1px solid #000;
    border-radius: 0;
    color: #000;
    cursor: pointer;
    font-family: var(--sans-ext, Arial, sans-serif);
    font-size: 16px;
    font-weight: 600;
    min-height: 52px;
    padding: 12px 24px;

    &:hover { background: #000; color: #fff; }
  }
  &__alert { background: #fff; border-left: 5px solid var(--crimson, #9e1b32); box-shadow: 0 10px 30px rgba(17, 17, 17, .07); color: #000; font-size: 16px; padding: 24px; }

  &__conflict-dialog {
    background: #fff;
    border: 0;
    box-shadow: 0 20px 70px rgba(0, 0, 0, .3);
    color: #000;
    font-family: var(--serif, Georgia, serif);
    margin: auto;
    max-height: calc(100vh - 48px);
    max-width: 680px;
    padding: 0;
    width: calc(100% - 32px);

    &::backdrop { background: rgba(0, 0, 0, .58); }
    form { display: flex; flex-direction: column; max-height: calc(100vh - 48px); padding: clamp(22px, 4vw, 38px); }
    h2 { font-family: var(--sans, Arial, sans-serif); font-size: 28px; line-height: 1.2; margin: 8px 0 14px; }
    h3 { font-family: var(--sans, Arial, sans-serif); font-size: 18px; margin: 24px 0 10px; }
    p { font-size: 16px; line-height: 1.55; margin: 0; }
  }

  &__conflict-products {
    border-bottom: 1px solid var(--hair, #dedbd5);
    border-top: 1px solid var(--hair, #dedbd5);
    list-style: none;
    margin: 0;
    min-height: 0;
    overflow-y: auto;
    padding: 4px 0;

    li { border-bottom: 1px solid var(--hair, #dedbd5); margin: 0; padding: 12px 4px; }
    li:last-child { border-bottom: 0; }
    strong, span { display: block; font-size: 15px; line-height: 1.4; }
    span { margin-top: 3px; }
  }

  &__remove-conflicting-brands {
    align-self: flex-start;
    background: transparent;
    border: 0;
    border-bottom: 1px solid currentColor;
    color: var(--crimson, #9e1b32);
    cursor: pointer;
    font-family: var(--sans, Arial, sans-serif);
    font-size: 16px;
    margin-top: 10px;
    padding: 2px 0;
  }

  &__conflict-actions {
    display: flex;
    flex: none;
    gap: 12px;
    justify-content: flex-end;
    padding-top: 22px;
  }

  &__conflict-cancel {
    background: #fff;
    border: 1px solid #000;
    color: #000;
    cursor: pointer;
    font-family: var(--sans-ext, Arial, sans-serif);
    font-size: 16px;
    font-weight: 600;
    min-height: 52px;
    padding: 12px 24px;
  }

  &__skeleton {
    display: grid;
    gap: 14px;
    padding: 16px 0;
    span { animation: configurator-pulse 1.25s ease-in-out infinite; background: #e8e6e1; display: block; height: 76px; }
  }
}

@keyframes configurator-pulse { 0%, 100% { opacity: .5; } 50% { opacity: 1; } }

@media (max-width: 767px) {
  .account-configurator {
    overflow-x: hidden;
    padding: 28px 14px 72px;

    &__inner,
    &__card,
    &__form,
    &__products,
    &__brand-list,
    &__category-list,
    &__prohibited-brands { max-width: 100%; min-width: 0; width: 100%; }

    &__header {
      h1 { font-size: 34px; }
      p { font-size: 16px; }
    }

    &__card { --card-padding-x: 16px; --card-padding-y: 20px; }
    &__form { gap: 30px; }
    &__form, &__search, &__bulk-import { grid-template-columns: minmax(0, 1fr); }
    &__search input,
    &__bulk-import textarea { min-width: 0; width: 100%; }
    &__search .account-configurator__button,
    &__bulk-import .account-configurator__button { width: 100%; }
    &__type,
    &__actions { grid-column: auto; }
    &__brand-list,
    &__category-list,
    &__prohibited-brands {
      > p,
      > small { height: auto; min-height: 0; margin-bottom: 14px; }
    }
    &__company { align-items: stretch; grid-template-columns: 1fr; }
    &__status { width: 100%; }
    &__check-list { padding-left: 10px; padding-right: 10px; }
    &__check-list li { padding-left: calc(var(--tree-depth, 0) * 12px); }

    &__approved {
      article {
        display: grid;
        gap: 6px;
        grid-template-columns: minmax(0, 1fr);
        margin-left: 0;
        margin-right: 0;
        padding-left: 0;
        padding-right: 0;
      }
      strong { overflow-wrap: anywhere; }
      article > button { justify-self: end; }
    }
    &__product { gap: 10px; min-width: 0; }
    &__product > div { min-width: 0; }
    &__product-image { flex-basis: 56px; height: 56px; width: 56px; }

    &__actions {
      align-items: stretch;
      flex-direction: column;
      gap: 10px;
      padding-bottom: 14px;
      padding-top: 14px;
    }
    &__actions .account-configurator__message:empty { display: none; }
    &__actions .account-configurator__button,
    &__actions .account-configurator__clear-filters { width: 100%; }
    &__conflict-dialog { max-height: calc(100vh - 24px); width: calc(100% - 20px); }
    &__conflict-dialog form { max-height: calc(100vh - 24px); padding: 20px 16px; }
    &__conflict-dialog h2 { font-size: 23px; }
    &__conflict-actions { flex-direction: column-reverse; }
    &__conflict-actions button { width: 100%; }
  }
}

