:root{
  /* ---- Twelve palette (brand guidelines p.28) ---- */
  --black:#000000;
  --white:#FFFFFF;
  --royal:#1F1ABC;
  --lavendar:#D6B2DE;
  --emerald:#00745B;
  --crimson:#E03249;
  --lemon:#EEFFAD;

  /* ---- derived neutrals (tints of black, never new hues) ---- */
  --ink:#000000;
  --ink-72:#000000;
  --ink-52:#000000;
  --ink-38:#9E9E9E;
  --hair:#E4E4E4;         /* hairline rules */
  --hair-strong:#C9C9C9;
  --paper:#FFFFFF;
  --paper-2:#F7F6F4;      /* faintest warm off-white for banding */
  --shadow:0 24px 60px -34px rgba(0,0,0,.45);

  /* ---- type ---- */
  /* All three licensed Dinamo families now embedded above. */
  --sans:"ABC Social",-apple-system,"Helvetica Neue",Arial,sans-serif;
  --sans-ext:"ABC Social Extended","ABC Social",-apple-system,Arial,sans-serif;
  --serif:"ABC Arizona Text",Georgia,"Times New Roman",serif;   /* licensed, embedded above */
  --word:"Bodoni Moda",Georgia,serif;

  /* ---- spacing (8pt) ---- */
  --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px; --s6:32px;
  --s7:48px; --s8:64px; --s9:96px; --s10:128px; --s11:160px;

  --gutter:56px;
  --section:128px;
  --maxw:1512px;

  --dur:.42s;
  --ease:cubic-bezier(.22,.61,.36,1);
}


